import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/song_info.dart';

import '_test_helpers.dart';
import 'package:nothingness/widgets/heroes/dot_hero.dart';

void main() {
  Future<void> capture(
    WidgetTester tester, {
    required String fileName,
    required double textScale,
  }) async {
    final trackPath = '/opt/nothingness/media/01-undercover-49.opus';

    const artist =
        'The Extremely Long Artist Name That Should Still Fit Above The Dot';
    const title =
        'An Equally Long Track Title That Should Not Clip Or Intersect The Pulsing Dot';

    final provider = FakeAudioPlayerProvider(
      songInfo: SongInfo(
        track: AudioTrack(
          path: trackPath,
          title: title,
          artist: artist,
        ),
        isPlaying: true,
        position: 0,
        duration: 200000,
      ),
      spectrumData: List<double>.filled(8, 1.0),
      isPlaying: true,
    );

    const configBase = DotScreenConfig(showSongInfo: true);
    final config = configBase.copyWith(textScale: textScale);

    await tester.pumpWidget(
      wrapWithProvider(
        provider,
        RepaintBoundary(
          child: const SizedBox(
            width: 500,
            height: 500,
            child: DotHero(config: config),
          ),
        ),
      ),
    );

    await tester.pumpAndSettle();

    final boundary = tester.renderObject(find.byType(RepaintBoundary).first);
    final image = await boundary.toImage(pixelRatio: 1.0);
    final bytes = await image.toByteData(format: ui.ImageByteFormat.png);

    final outDir = Directory('.tmp');
    if (!await outDir.exists()) {
      await outDir.create(recursive: true);
    }
    final outPath = outDir.path + '/' + fileName;
    await File(outPath).writeAsBytes(bytes!.buffer.asUint8List());
  }

  testWidgets('dot hero song-info overlay keeps layout intact at text scales',
      (tester) async {
    await capture(
      tester,
      fileName: 'dot_hero_songinfo_normal.png',
      textScale: 1.0,
    );
    await capture(
      tester,
      fileName: 'dot_hero_songinfo_max.png',
      textScale: 1.5,
    );

    // If we got here, both PNGs were rendered.
    expect(File('.tmp/dot_hero_songinfo_normal.png').existsSync(), isTrue);
    expect(File('.tmp/dot_hero_songinfo_max.png').existsSync(), isTrue);
  });
}

